-- composition of rule kernels L:replace_distinct_aggregate x P:FilterPushdown (datafusion), template graft_scalar
SELECT DISTINCT '0 days'::interval AS c0, make_array('a', 'b') AS c1, '1970-01-01'::date AS c2 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c3 = a2.c3)) WHERE COALESCE ((LENGTH ((SELECT STRING_AGG ('NaN'::text, ',' ORDER BY 'NaN'::text) FROM (SELECT * FROM tp WHERE (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0, 'NaN'::text AS c1 UNION SELECT '1999-12-31'::date AS c0, 'abc'::text AS c1) AS kb) >= 0) AS a3)) <> a2.c0), (a1.c0 IS DISTINCT FROM a2.c0));
